import { createHash } from 'node:crypto';
import { readFile } from 'node:fs/promises';
import * as api from '/Users/aidenybai/Developer/bippy-engine262-symbolic/packages/bippy-analyzer/engine/dist/engine.mjs';
const previous = api.surroundingAgent;
const observations = [];
for (const expression of ["eval('counter++')", "Function('return 7')()", "JSON.parse('7')"]) {
  const agent = new api.Agent({startEventLoop:false});
  api.setSurroundingAgent(agent);
  const realm = new api.ManagedRealm();
  realm.pushTopContext();
  api.X(api.CreateDataPropertyOrThrow(realm.GlobalObject,'enabled',api.BooleanValue.createAbstract()));
  const script = api.EnsureCompletion(realm.compileScript(`var counter=0,caught=false; if(enabled){try{${expression}}catch(error){caught=true}}`));
  if(script.Type!=='normal')throw Error('Compile failed');
  agent.evaluate(api.ScriptEvaluation(script.Value),()=>{},false);
  const pause=agent.resumeEvaluate({pauseOnAbstractBoolean:true});
  if(pause.done || !pause.value)throw Error('Expected pause');
  const saved=agent.captureEvaluation({capture:()=>({restore:()=>{}})});
  const before=agent.parsedSources.size;
  let compileHooks=0,parsedHooks=0,errorMessage;
  agent.hostDefinedOptions.hostHooks={HostEnsureCanCompileStrings:()=>{compileHooks++;return api.NormalCompletion(undefined);}};
  agent.hostDefinedOptions.onScriptParsed=()=>{parsedHooks++;};
  try{
    agent.resumeEvaluate({abstractBooleanDecision:{resume:'abstract-boolean',decision:pause.value,value:true}});
  }catch(error){errorMessage=error instanceof Error?error.message:String(error);}
  observations.push({expression,compileHooks,parsedHooks,registryDelta:agent.parsedSources.size-before,guestCaught:realm.GlobalObject.properties.get('caught')?.Value===api.Value.true,errorMessage});
  saved.release();
  agent.executionContextStack.length=0;
}
api.setSurroundingAgent(previous);
console.log(JSON.stringify({engine:createHash('sha256').update(await readFile('/Users/aidenybai/Developer/bippy-engine262-symbolic/packages/bippy-analyzer/engine/dist/engine.mjs')).digest('hex'),observations},null,2));
